 17→// Ensure ClaudeCodeAgent implements HookSupport
 18→var _ agent.HookSupport = (*ClaudeCodeAgent)(nil)
 19→
 20→// Claude Code hook names - these become subcommands under `entire hooks claude-code`
 21→const (
 22→	HookNameSessionStart     = "session-start"
 23→	HookNameSessionEnd       = "session-end"
 24→	HookNameStop             = "stop"
 25→	HookNameUserPromptSubmit = "user-prompt-submit"
 26→	HookNamePreTask          = "pre-task"
 27→	HookNamePostTask         = "post-task"
 28→	HookNamePostTodo         = "post-todo"
 29→)
