 31→// ClaudeSettingsFileName is the settings file used by Claude Code.
 32→// This is Claude-specific and not shared with other agents.
 33→const ClaudeSettingsFileName = "settings.json"
 34→
 35→// metadataDenyRule blocks Claude from reading Entire session metadata
 36→const metadataDenyRule = "Read(./.entire/metadata/**)"
 37→
 38→// entireHookPrefixes are command prefixes that identify Entire hooks (both old and new formats)
 39→var entireHookPrefixes = []string{
 40→	"entire ",
 41→	"go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go ",
 42→}
