251→// UninstallHooks removes Entire hooks from Claude Code settings.
252→func (c *ClaudeCodeAgent) UninstallHooks(ctx context.Context) error {
253→	// Use repo root to find .claude directory when run from a subdirectory
254→	repoRoot, err := paths.WorktreeRoot(ctx)
255→	if err != nil {
256→		repoRoot = "." // Fallback to CWD if not in a git repo
257→	}
258→	settingsPath := filepath.Join(repoRoot, ".claude", ClaudeSettingsFileName)
259→	data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
260→	if err != nil {
261→		return nil //nolint:nilerr // No settings file means nothing to uninstall
262→	}
263→
264→	var rawSettings map[string]json.RawMessage
265→	if err := json.Unmarshal(data, &rawSettings); err != nil {
266→		return fmt.Errorf("failed to parse settings.json: %w", err)
267→	}
268→
269→	// rawHooks preserves unknown hook types (e.g., "Notification", "SubagentStop")
270→	var rawHooks map[string]json.RawMessage
271→	if hooksRaw, ok := rawSettings["hooks"]; ok {
272→		if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
273→			return fmt.Errorf("failed to parse hooks: %w", err)
274→		}
275→	}
276→	if rawHooks == nil {
277→		rawHooks = make(map[string]json.RawMessage)
278→	}
279→
280→	// Parse only the hook types we need to modify
281→	var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse []ClaudeHookMatcher
282→	parseHookType(rawHooks, "SessionStart", &sessionStart)
283→	parseHookType(rawHooks, "SessionEnd", &sessionEnd)
284→	parseHookType(rawHooks, "Stop", &stop)
285→	parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
286→	parseHookType(rawHooks, "PreToolUse", &preToolUse)
287→	parseHookType(rawHooks, "PostToolUse", &postToolUse)
288→
289→	// Remove Entire hooks from all hook types
290→	sessionStart = removeEntireHooks(sessionStart)
291→	sessionEnd = removeEntireHooks(sessionEnd)
292→	stop = removeEntireHooks(stop)
293→	userPromptSubmit = removeEntireHooks(userPromptSubmit)
294→	preToolUse = removeEntireHooksFromMatchers(preToolUse)
295→	postToolUse = removeEntireHooksFromMatchers(postToolUse)
296→
297→	// Marshal modified hook types back to rawHooks
298→	marshalHookType(rawHooks, "SessionStart", sessionStart)
299→	marshalHookType(rawHooks, "SessionEnd", sessionEnd)
300→	marshalHookType(rawHooks, "Stop", stop)
301→	marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
302→	marshalHookType(rawHooks, "PreToolUse", preToolUse)
303→	marshalHookType(rawHooks, "PostToolUse", postToolUse)
304→
305→	// Also remove the metadata deny rule from permissions
306→	var rawPermissions map[string]json.RawMessage
307→	if permRaw, ok := rawSettings["permissions"]; ok {
308→		if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
309→			// If parsing fails, just skip permissions cleanup
310→			rawPermissions = nil
311→		}
312→	}
313→
314→	if rawPermissions != nil {
315→		if denyRaw, ok := rawPermissions["deny"]; ok {
316→			var denyRules []string
317→			if err := json.Unmarshal(denyRaw, &denyRules); err == nil {
318→				// Filter out the metadata deny rule
319→				filteredRules := make([]string, 0, len(denyRules))
320→				for _, rule := range denyRules {
321→					if rule != metadataDenyRule {
322→						filteredRules = append(filteredRules, rule)
323→					}
324→				}
325→				if len(filteredRules) > 0 {
326→					denyJSON, err := json.Marshal(filteredRules)
327→					if err == nil {
328→						rawPermissions["deny"] = denyJSON
329→					}
330→				} else {
331→					// Remove empty deny array
332→					delete(rawPermissions, "deny")
333→				}
334→			}
335→		}
336→
337→		// If permissions is empty, remove it entirely
338→		if len(rawPermissions) > 0 {
339→			permJSON, err := json.Marshal(rawPermissions)
340→			if err == nil {
341→				rawSettings["permissions"] = permJSON
342→			}
343→		} else {
344→			delete(rawSettings, "permissions")
345→		}
346→	}
347→
348→	// Marshal hooks back (preserving unknown hook types)
349→	if len(rawHooks) > 0 {
350→		hooksJSON, err := json.Marshal(rawHooks)
351→		if err != nil {
352→			return fmt.Errorf("failed to marshal hooks: %w", err)
353→		}
354→		rawSettings["hooks"] = hooksJSON
355→	} else {
356→		delete(rawSettings, "hooks")
357→	}
358→
359→	// Write back
360→	output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
361→	if err != nil {
362→		return fmt.Errorf("failed to marshal settings: %w", err)
363→	}
364→	if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
365→		return fmt.Errorf("failed to write settings.json: %w", err)
366→	}
367→	return nil
368→}
