 21→// Cursor hook names - these become subcommands under `entire hooks cursor`
 22→const (
 23→	HookNameSessionStart       = "session-start"
 24→	HookNameSessionEnd         = "session-end"
 25→	HookNameBeforeSubmitPrompt = "before-submit-prompt"
 26→	HookNameStop               = "stop"
