280→// AreHooksInstalled checks if Entire hooks are installed.
281→func (c *CursorAgent) AreHooksInstalled(ctx context.Context) bool {
282→	worktreeRoot, err := paths.WorktreeRoot(ctx)
283→	if err != nil {
284→		worktreeRoot = "."
285→	}
286→	hooksPath := filepath.Join(worktreeRoot, ".cursor", HooksFileName)
287→	data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
288→	if err != nil {
289→		return false
290→	}
291→
292→	var hooksFile CursorHooksFile
293→	if err := json.Unmarshal(data, &hooksFile); err != nil {
294→		return false
295→	}
296→
297→	return hasEntireHook(hooksFile.Hooks.SessionStart) ||
298→		hasEntireHook(hooksFile.Hooks.SessionEnd) ||
299→		hasEntireHook(hooksFile.Hooks.BeforeSubmitPrompt) ||
300→		hasEntireHook(hooksFile.Hooks.Stop) ||
301→		hasEntireHook(hooksFile.Hooks.PreCompact) ||
302→		hasEntireHook(hooksFile.Hooks.SubagentStart) ||
303→		hasEntireHook(hooksFile.Hooks.SubagentStop)
304→}
