318→// parseCursorHookType parses a specific hook type from rawHooks into the target slice.
319→// Silently ignores parse errors (leaves target unchanged).
320→func parseCursorHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]CursorHookEntry) {
321→	if data, ok := rawHooks[hookType]; ok {
322→		//nolint:errcheck,gosec // Intentionally ignoring parse errors - leave target as nil/empty
323→		json.Unmarshal(data, target)
324→	}
325→}
326→
327→// marshalCursorHookType marshals a hook type back into rawHooks.
328→// If the slice is empty, removes the key from rawHooks.
329→func marshalCursorHookType(rawHooks map[string]json.RawMessage, hookType string, entries []CursorHookEntry) {
330→	if len(entries) == 0 {
331→		delete(rawHooks, hookType)
332→		return
333→	}
334→	data, err := json.Marshal(entries)
335→	if err != nil {
336→		return // Silently ignore marshal errors (shouldn't happen)
337→	}
338→	rawHooks[hookType] = data
339→}
