341→// Helper functions for hook management
342→
343→func hookCommandExists(entries []CursorHookEntry, command string) bool {
344→	for _, entry := range entries {
345→		if entry.Command == command {
346→			return true
347→		}
348→	}
349→	return false
350→}
351→
352→func isEntireHook(command string) bool {
353→	for _, prefix := range entireHookPrefixes {
354→		if strings.HasPrefix(command, prefix) {
355→			return true
356→		}
357→	}
358→	return false
359→}
360→
361→func hasEntireHook(entries []CursorHookEntry) bool {
362→	for _, entry := range entries {
363→		if isEntireHook(entry.Command) {
364→			return true
365→		}
366→	}
367→	return false
368→}
369→
370→func removeEntireHooks(entries []CursorHookEntry) []CursorHookEntry {
371→	result := make([]CursorHookEntry, 0, len(entries))
372→	for _, entry := range entries {
373→		if !isEntireHook(entry.Command) {
374→			result = append(result, entry)
375→		}
376→	}
377→	return result
378→}
