 18→// HooksFileName is the hooks file managed by Entire for Copilot CLI.
 19→const HooksFileName = "entire.json"
 20→
 21→// hooksDir is the directory within the repo where Copilot CLI looks for hook configs.
 22→const hooksDir = ".github/hooks"
 23→
 24→// entireHookPrefixes are command prefixes that identify Entire hooks in the bash field.
 25→var entireHookPrefixes = []string{
 26→	"entire ",
 27→	"go run ${COPILOT_PROJECT_DIR}/cmd/entire/main.go ",
 28→}
 29→
 30→// hookConfigKey maps our kebab-case hook names to camelCase JSON keys.
 31→var hookConfigKey = map[string]string{
 32→	HookNameUserPromptSubmitted: "userPromptSubmitted",
 33→	HookNameSessionStart:        "sessionStart",
 34→	HookNameAgentStop:           "agentStop",
 35→	HookNameSessionEnd:          "sessionEnd",
 36→	HookNameSubagentStop:        "subagentStop",
 37→	HookNamePreToolUse:          "preToolUse",
 38→	HookNamePostToolUse:         "postToolUse",
 39→	HookNameErrorOccurred:       "errorOccurred",
 40→}
 41→
 42→// InstallHooks installs Copilot CLI hooks in .github/hooks/entire.json.
 43→// If force is true, removes existing Entire hooks before installing.
 44→// Returns the number of hooks installed.
 45→// Unknown top-level fields and hook types are preserved on round-trip.
 46→func (c *CopilotCLIAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
 47→	worktreeRoot, err := paths.WorktreeRoot(ctx)
 48→	if err != nil {
 49→		worktreeRoot = "."
 50→	}
 51→
 52→	hooksPath := filepath.Join(worktreeRoot, hooksDir, HooksFileName)
 53→
 54→	// Use raw maps to preserve unknown fields on round-trip
 55→	var rawFile map[string]json.RawMessage
 56→	var rawHooks map[string]json.RawMessage
 57→
 58→	existingData, readErr := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
 59→	switch {
 60→	case readErr == nil:
 61→		if err := json.Unmarshal(existingData, &rawFile); err != nil {
 62→			return 0, fmt.Errorf("failed to parse existing %s: %w", HooksFileName, err)
 63→		}
 64→		if hooksRaw, ok := rawFile["hooks"]; ok {
 65→			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
 66→				return 0, fmt.Errorf("failed to parse hooks in %s: %w", HooksFileName, err)
 67→			}
 68→		}
 69→		if _, ok := rawFile["version"]; !ok {
 70→			rawFile["version"] = json.RawMessage(`1`)
 71→		}
 72→	case errors.Is(readErr, os.ErrNotExist):
 73→		rawFile = map[string]json.RawMessage{
 74→			"version": json.RawMessage(`1`),
 75→		}
 76→	default:
 77→		return 0, fmt.Errorf("failed to read %s: %w", HooksFileName, readErr)
 78→	}
 79→
 80→	if rawHooks == nil {
 81→		rawHooks = make(map[string]json.RawMessage)
 82→	}
 83→
 84→	// Parse existing entries for each hook type we manage
 85→	hookEntries := make(map[string][]CopilotHookEntry)
 86→	for _, hookName := range c.HookNames() {
 87→		key := hookConfigKey[hookName]
 88→		var entries []CopilotHookEntry
 89→		if err := parseCopilotHookType(rawHooks, key, &entries); err != nil {
 90→			return 0, fmt.Errorf("failed to parse %s hooks: %w", key, err)
 91→		}
 92→		hookEntries[hookName] = entries
 93→	}
 94→
 95→	// If force, remove existing Entire hooks first
 96→	if force {
 97→		for hookName, entries := range hookEntries {
 98→			hookEntries[hookName] = removeEntireHooks(entries)
 99→		}
100→	}
101→
102→	// Define command prefix
103→	var cmdPrefix string
104→	if localDev {
105→		cmdPrefix = "go run ${COPILOT_PROJECT_DIR}/cmd/entire/main.go hooks copilot-cli "
106→	} else {
107→		cmdPrefix = "entire hooks copilot-cli "
108→	}
109→
110→	count := 0
111→
112→	// Add hooks that don't already exist
113→	for _, hookName := range c.HookNames() {
114→		cmd := cmdPrefix + hookName
115→		entries := hookEntries[hookName]
116→		if !hookBashExists(entries, cmd) {
117→			entries = append(entries, CopilotHookEntry{
118→				Type:    "command",
119→				Bash:    cmd,
120→				Comment: "Entire CLI",
121→			})
122→			hookEntries[hookName] = entries
123→			count++
124→		}
125→	}
126→
127→	if count == 0 {
128→		return 0, nil
129→	}
130→
131→	// Marshal modified hook types back into rawHooks
132→	for _, hookName := range c.HookNames() {
133→		key := hookConfigKey[hookName]
134→		if err := marshalCopilotHookType(rawHooks, key, hookEntries[hookName]); err != nil {
135→			return 0, fmt.Errorf("failed to marshal %s hooks: %w", key, err)
136→		}
137→	}
138→
139→	// Marshal hooks and update raw file
140→	hooksJSON, err := json.Marshal(rawHooks)
141→	if err != nil {
142→		return 0, fmt.Errorf("failed to marshal hooks: %w", err)
143→	}
144→	rawFile["hooks"] = hooksJSON
145→
146→	// Write to file
147→	if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
148→		return 0, fmt.Errorf("failed to create %s directory: %w", hooksDir, err)
149→	}
150→
151→	output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
152→	if err != nil {
153→		return 0, fmt.Errorf("failed to marshal %s: %w", HooksFileName, err)
154→	}
155→
156→	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
157→		return 0, fmt.Errorf("failed to write %s: %w", HooksFileName, err)
158→	}
159→
160→	return count, nil
161→}
