230→// AreHooksInstalled checks if Entire hooks are installed in the Copilot CLI config.
231→func (c *CopilotCLIAgent) AreHooksInstalled(ctx context.Context) bool {
232→	worktreeRoot, err := paths.WorktreeRoot(ctx)
233→	if err != nil {
234→		worktreeRoot = "."
235→	}
236→	hooksPath := filepath.Join(worktreeRoot, hooksDir, HooksFileName)
237→	data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
238→	if err != nil {
239→		if !errors.Is(err, os.ErrNotExist) {
240→			logging.Warn(ctx, "copilot-cli: failed to read hooks file", "path", hooksPath, "err", err)
241→		}
242→		return false
243→	}
244→
245→	var hooksFile CopilotHooksFile
246→	if err := json.Unmarshal(data, &hooksFile); err != nil {
247→		logging.Warn(ctx, "copilot-cli: failed to parse hooks file", "path", hooksPath, "err", err)
248→		return false
249→	}
250→
251→	return hasEntireHook(hooksFile.Hooks.UserPromptSubmitted) ||
252→		hasEntireHook(hooksFile.Hooks.SessionStart) ||
253→		hasEntireHook(hooksFile.Hooks.AgentStop) ||
254→		hasEntireHook(hooksFile.Hooks.SessionEnd) ||
255→		hasEntireHook(hooksFile.Hooks.SubagentStop) ||
256→		hasEntireHook(hooksFile.Hooks.PreToolUse) ||
257→		hasEntireHook(hooksFile.Hooks.PostToolUse) ||
258→		hasEntireHook(hooksFile.Hooks.ErrorOccurred)
259→}
