221→	// Create settings with hook types we don't handle (hypothetical future Gemini hook types)
222→	writeGeminiSettings(t, tempDir, `{
223→  "hooks": {
224→    "FutureHook": [
225→      {
226→        "matcher": "",
227→        "hooks": [{"name": "future-hook", "type": "command", "command": "echo future"}]
228→      }
229→    ],
230→    "AnotherNewHook": [
231→      {
232→        "matcher": "pattern",
233→        "hooks": [{"name": "another-hook", "type": "command", "command": "echo another"}]
234→      }
235→    ]
236→  }
237→}`)
238→
239→	agent := &GeminiCLIAgent{}
