271→	}
272→
273→	// Verify AnotherNewHook content including matcher
274→	var anotherMatchers []GeminiHookMatcher
275→	if err := json.Unmarshal(rawHooks["AnotherNewHook"], &anotherMatchers); err != nil {
276→		t.Fatalf("failed to parse AnotherNewHook: %v", err)
