279→		if anotherMatchers[0].Matcher != "pattern" {
280→			t.Errorf("AnotherNewHook matcher = %q, want %q", anotherMatchers[0].Matcher, "pattern")
281→		}
282→	}
283→
284→	// Verify our hooks were also installed
285→	if _, ok := rawHooks["SessionStart"]; !ok {
286→		t.Errorf("SessionStart hook should have been installed")
287→	}
